import{_ as t,o,c as r,a2 as a}from"./chunks/framework.hw3Av5Vn.js";const s="/llamatron/assets/progression_editor.p4HX8zee.svg",d="/llamatron/assets/chords_editor.BwNFeHuW.svg",u=JSON.parse('{"title":"Progression","description":"","frontmatter":{},"headers":[],"relativePath":"generators/PROGRESSION.md","filePath":"generators/PROGRESSION.md"}'),n={name:"generators/PROGRESSION.md"};function h(c,e,i,l,p,g){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="progression" tabindex="-1">Progression <a class="header-anchor" href="#progression" aria-label="Permalink to &quot;Progression&quot;">​</a></h1><p><img src="'+s+'" alt="A progression&#39;s settings"></p><p>A progression plays a clip through a chord progression. Write a short figure over chord I, a riff, an arpeggio, a bass line or a chord, and the progression moves the clip&#39;s notes to each of its chords in turn, so that one bar becomes a whole section, and changing the progression rewrites the section without touching the pattern.</p><h2 id="chord-movement" tabindex="-1">Chord Movement <a class="header-anchor" href="#chord-movement" aria-label="Permalink to &quot;Chord Movement&quot;">​</a></h2><p>The chords are degrees of the scale. A plain degree moves every note that many steps up the scale, less one, so the scale decides whether the chord is major or minor: in C major, a C major chord moved to 6 plays A minor, and in C minor the same progression is minor. A degree with a sharp or a flat moves the notes by exact half steps instead, keeping the figure&#39;s own sound, which is how borrowed chords such as the rock ♭VII (B♭ major in C major) come out right. A note the pattern writes outside the scale keeps its distance from the scale note below it, so a figure written as a <code>dom7</code> chord stays a dominant seventh on every chord. The rhythm, velocity and everything else stay as written, and a drum pattern is left alone. Each chord lasts Every, a bar by default, counted from the clip&#39;s start, the progression looping for as long as the clip plays.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td>Name</td><td><code>Enter</code> renames it, and every chain using it follows.</td></tr><tr><td>Every</td><td>How long each chord lasts, <code>1 bar</code> by default.</td></tr><tr><td>Chords</td><td>The chords as Roman numerals in the song&#39;s scale. <code>Enter</code> opens the chord editor.</td></tr><tr><td>Restart</td><td>When it starts over, as <a href="./../GENERATORS#restart">Generators</a> describes; with &quot;whole song&quot; a progression runs on across scenes.</td></tr></tbody></table><h2 id="chord-editor" tabindex="-1">Chord Editor <a class="header-anchor" href="#chord-editor" aria-label="Permalink to &quot;Chord Editor&quot;">​</a></h2><p><img src="'+d+'" alt="The chords of a progression, as numerals and names in the song&#39;s scale"></p><p>The chord editor draws each chord as a column: a bar rising to its degree, then its Roman numeral (upper case for major, lower case for minor, ° for diminished) and its name in the song&#39;s scale, such as <code>Am</code>, then a <code>#/b</code> row, the Quality, Tens. and Scale rows, and an <code>Inv.</code> row. The status line names the chord under the cursor and its notes. A new progression has one chord, I, which changes nothing until edited.</p><table tabindex="0"><thead><tr><th>Key</th><th>What it does</th></tr></thead><tbody><tr><td>Arrows</td><td>Left and Right move along the chords, Up and Down between the rows, stopping at the edges.</td></tr><tr><td><code>[</code>, <code>]</code></td><td>On the Chord row, step the degree from 1 to 7; on the <code>#/b</code> and <code>Inv.</code> rows, step through the choices, as <code>Space</code> and <code>Enter</code> do.</td></tr><tr><td><code>Enter</code></td><td>On the Quality, Tens. and Scale rows, opens the <a href="./../PATTERNS#chord-selector">Chord Selector</a>, the one the pattern editor opens, on that row&#39;s list; <code>Space</code> steps to the next choice and <code>Bksp</code> clears.</td></tr><tr><td>Digits</td><td>Type a degree, or an inversion.</td></tr><tr><td><code>I</code>, <code>D</code></td><td>Insert a chord I before the cursor&#39;s, or remove the cursor&#39;s, keeping 1 to 16 chords.</td></tr><tr><td><code>H</code></td><td>Opens a picker of 24 named progressions, from Pop to Andalusian, and fills the chords with the one chosen, matched to the song&#39;s scale.</td></tr></tbody></table><p>An inversion of 1 moves each chord&#39;s lowest note up an octave, and 2 its lowest two.</p><h2 id="chords-outside-the-scale" tabindex="-1">Chords Outside the Scale <a class="header-anchor" href="#chords-outside-the-scale" aria-label="Permalink to &quot;Chords Outside the Scale&quot;">​</a></h2><p>Three rows let a chord leave the song&#39;s scale. Each chord is worked out in one order: the Scale row picks the scale, the Chord and <code>#/b</code> rows pick the root in that scale, the Quality row names the chord if set, and the Tens. row adds notes on top.</p><table tabindex="0"><thead><tr><th>Row</th><th>What it does</th></tr></thead><tbody><tr><td>Scale</td><td>A scale type on the song&#39;s root that this chord borrows, blank for the song&#39;s own. In C major, chord 6 with the Scale &quot;Minor&quot; is A flat major, and the notes of the pattern between the chord&#39;s notes come from C minor too while the chord plays. Because the root is always the song&#39;s, a change of root carries every borrowed chord with it.</td></tr><tr><td>Quality</td><td>A named chord in place of the one the scale builds, blank for the scale&#39;s own. In C major, chord 3 is E minor, and with the Quality <code>M</code> it is E major: the pattern&#39;s notes that are the chord&#39;s third, fifth and seventh are moved to match.</td></tr><tr><td>Tens.</td><td>Tensions: <code>b9</code>, <code>9</code>, <code>#9</code>, <code>11</code>, <code>#11</code>, <code>b13</code> and <code>13</code>. Each sets the pattern&#39;s note that lies between the chord&#39;s notes, and is added on top of a chord the pattern plays.</td></tr></tbody></table><h2 id="applying-the-generator" tabindex="-1">Applying the Generator <a class="header-anchor" href="#applying-the-generator" aria-label="Permalink to &quot;Applying the Generator&quot;">​</a></h2><p>Add the progression to a chain, as <code>progression: name</code>, and give clips that chain; <a href="./../CONCEPTS#chord-progressions">Concepts</a> walks through it. <code>examples/learning/06_chord_progression_generator.yml</code> plays three one-bar patterns through five progressions, and <code>examples/learning/07_blues_chords.yml</code> is a twelve-bar blues.</p>',17)])])}const b=t(n,[["render",h]]);export{u as __pageData,b as default};
